import unittest

from solucao import montar_etiqueta


class TestAEtiquetaDaPrateleira(unittest.TestCase):
    def test_monta_a_etiqueta(self):
        """montar_etiqueta limpa o nome e monta a etiqueta da posicao 45"""
        self.assertEqual(montar_etiqueta("  parafuso sextavado ", "45"), "PARAFUSO-SEXTAVADO | E-05")

    def test_corta_o_cadastro_do_fornecedor(self):
        """montar_etiqueta corta o cadastro depois do jogo da velha e muda de prateleira"""
        self.assertEqual(montar_etiqueta("porca 8mm#ACME", "11"), "PORCA-8MM | B-01")

    def test_peca_fragil(self):
        """montar_etiqueta poe o prefixo FRAGIL e apaga o asterisco do nome"""
        self.assertEqual(montar_etiqueta("*tela sensivel", "3"), "FRAGIL-TELA-SENSIVEL | A-03")

    def test_fim_da_prateleira(self):
        """montar_etiqueta mantem a letra no fim da prateleira e o lugar com dois digitos"""
        self.assertEqual(montar_etiqueta("arruela", "10"), "ARRUELA | A-10")
